def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The less frequent color forms the enclosing strokes; fill enclosed cells
    # of the other (background) color with 4-neighbor exterior connectivity.
    colors = set(sum(g, []))
    fg = min(colors, key=lambda v: sum(row.count(v) for row in g))
    bg = next(v for v in colors if v != fg)
    seen = set()
    stack = []
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and g[r][c] == bg:
                seen.add((r, c))
                stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w and (y, x) not in seen and g[y][x] == bg:
                seen.add((y, x))
                stack.append((y, x))
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg and (r, c) not in seen:
                g[r][c] = 4
    return g

